# DK VBA.  Viborg - Aalestrup
#
let va = path("d3.dk.vba");
let vib = path("d3.dk.vba.vib");

with detail = 4, railway = :first :pax :removed {
    # point.dk.Viborg  dk.LST

    with link = "line.dk.VBA" {
        track(:lor, va[:vib + 549m, :vib.ya] >> 1mo);
        track(:lor,
                va[:vib.ya - 0.1dl, :vib.ya] >> 1mo
            ..  va[:vib.xa, :vib.xa + 0.1dl]
        );
        track(va[:vib.xa, :mar.yv - 0.99seg]);
        track(:lor, va[:mar.yv - 1seg, :mar.yv]);

        track(:lor, vib[:vib.ym, :vib.ym + 0.5seg]);
        track(vib[:vib.ym + 0.49seg, :mar.yv - 0.99seg]);
        track(:ror, vib[:mar.yv - 1seg, :mar.yv]);
    }

    with link = "point.dk.Margrethelund", railway = :station {
        track(va[:mar.yv, :mar + 0.5sw]);
        marker(:right :de.hp, va[:mar] >> 0.5mt);
        station(:right, va[:mar] >> 0.5mt >> 1sh + (1.4dt, 1.1dt),
            "Margrethelund", "VBA: 4,1"
        );
    }

    with link = "line.dk.VBA" {
        track(va[:mar + 0.49sw, :mar + 1.51km]);
        line_label(:right:w, va[:mar + 1.5km] >> 0.5mt, (0dt, 0.2dt), "VBA");
        track(va[:mar + 1.49km, :log - 0.49sw]);
    }

    with link = "point.dk.Løgstrup", railway = :station {
        track(va[:log - 0.5sw, :log + 0.5sw]);
        marker(:left :de.bf, va[:log] << 0.5mt);
        station(:left, va[:log] << 0.5mt << 1sh + (-1.7dt, 1.4dt),
            "Løgstrup", "VBA: 10,0"
        );
    }

    with link = "line.dk.VBA" {
        track(va[:log + 0.49sw, :hja - 0.49sw]);
    }

    with link = "point.dk.Hjarbæk", railway = :station {
        track(va[:hja - 0.5sw, :hja + 0.5sw]);
        marker(:left :de.hp, va[:hja] << 0.5mt);
        station(:left, va[:hja] << 0.5mt << 1sh + (-2dt, 0.9dt),
            "Hjarbæk", "VBA: 11,7"
        );
    }

    with link = "line.dk.VBA" {
        track(va[:hja + 0.49sw, :kol - 0.49sw]);
    }

    with link = "point.dk.Kølsen", railway = :station {
        track(va[:kol - 0.5sw, :kol + 0.5sw]);
        marker(:right :de.hp, va[:kol] >> 0.5mt);
        station(:right:left_align, va[:kol] >> 0.5mt >> 1sh + (1.5dt, 1.3dt),
            "Kølsen", "VBA: 14,0"
        );
    }

    with link = "line.dk.VBA" {
        track(va[:kol + 0.49sw, :ned - 0.49sw]);
    }

    with link = "point.dk.Nederhede", railway = :station {
        track(va[:ned - 0.5sw, :ned + 0.5sw]);
        marker(:left :de.hp, va[:ned] << 0.5mt);
        station(:top, va[:ned] << 0.5mt << 1sh + (-1.5dt, -1dt),
            "Nederhede", "VBA: 15,7"
        );
    }

    with link = "line.dk.VBA" {
        track(va[:ned + 0.49sw, :ska - 0.49sw]);
    }

    with link = "point.dk.Skals", railway = :station {
        track(va[:ska - 0.5sw, :ska + 0.5sw]);
        marker(:left :de.bf, va[:ska] << 0.5mt);
        station(:top, va[:ska] << 0.5mt << 1sh << 0.8dt,
            "Skals", "VBA: 17,6"
        );
    }

    with link = "line.dk.VBA" {
        track(va[:ska + 0.49sw, :ska + 2.31km]);
        line_label(:right:w, va[:ska + 2.3km] >> 0.5mt, (0dt, 0.4dt), "VBA");
        track(va[:ska + 2.29km, :skr - 0.49sw]);
    }

    with link = "point.dk.Skringstrup", railway = :station {
        track(va[:skr - 0.5sw, :skr + 0.5sw]);
        marker(:right :de.hp, va[:skr] >> 0.5mt);
        station(:right, va[:skr] >> 0.5mt >> 1sh + (1.5dt, 1.4dt),
            "Skringstrup", "VBA: 21,5"
        );
    }

    with link = "line.dk.VBA" {
        track(va[:skr + 0.49sw, :nor - 0.49sw]);
    }

    with link = "point.dk.Nørdam", railway = :station {
        track(va[:nor - 0.5sw, :nor + 0.5sw]);
        marker(:right :de.hp, va[:nor] >> 0.5mt);
        station(:bottom, va[:nor] >> 0.5mt >> 1sh + (1.4dt, 0.8dt),
            "Nørdam", "VBA: 24,5"
        );
    }

    with link = "line.dk.VBA" {
        track(va[:nor + 0.49sw, :mol - 0.49sw]);
    }

    with link = "point.dk.Møldrup", railway = :station {
        track(va[:mol - 0.5sw, :mol + 0.5sw]);
        marker(:left :de.bf, va[:mol] << 0.5mt);
        station(:top, va[:mol] << 0.5mt << 1sh + (-1.8dt, -1.3dt),
            "Møldrup", "VBA: 27,1"
        );
    }

    with link = "line.dk.VBA" {
        track(va[:mol + 0.49sw, :hva - 0.49sw]);
    }

    with link = "point.dk.Hvam", railway = :station {
        track(va[:hva - 0.5sw, :hva + 0.5sw]);
        marker(:left :de.bf, va[:hva] << 0.5mt);
        station(:left:right_align, va[:hva] << 0.5mt << 1sh + (-1.7dt, 1.2dt),
            "Hvam", "VBA: 32,9 "
        );
    }

    with link = "line.dk.VBA" {
        track(va[:hva + 0.49sw, :hva + 2.11km]);
        line_label(:right:w, va[:hva + 2.1km] >> 0.5mt, "VBA");
        track(va[:hva + 2.09km, :aal.yh - 0.99seg]);
        track(:ror, va[:aal.yh - 1seg, :aal.yh + 0.1dl]);
    }

    # point.dk.Aalestrup  dk.HLS
}

